#include <vector>
#include "dispatch_r9150.hpp"
#include <cmath>
#include <cassert>
#include <iostream>
#include <algorithm>
float reduce(const std::vector<float>&v,size_t block){std::vector<float>x(block);for(size_t t=0;t<block;++t)for(size_t k=t;k<v.size();k+=block)x[t]+=v[k];for(size_t stride=block/2;stride;stride/=2)for(size_t t=0;t<stride;++t)x[t]+=x[t+stride];return x[0];}
int main(){size_t checks=0;for(size_t C:{1ul,2ul,4ul,8ul,16ul,32ul})for(size_t W:{1ul,2ul,4ul,8ul})if(C*W<=64)for(size_t block:{128ul,256ul}){assert(block%64==0&&block>=128&&(3*128+block)*4<=65536&&C*6*128>0);++checks;}for(size_t seed=0;seed<256;++seed){std::vector<float>x(128);for(size_t i=0;i<128;++i)x[i]=std::sin(float(i+seed)*.173f);auto a=reduce(x,256),b=reduce(x,128);assert(std::isfinite(a)&&std::isfinite(b)&&std::abs(a-b)<1e-4f);++checks;}for(size_t C:{1ul,2ul,4ul,8ul,16ul,32ul})for(size_t W:{1ul,2ul,4ul,8ul,64ul,512ul}){kda_dispatch_r9150::Input g;g.C=C;g.T=C*W;g.H=6;g.D=128;g.pool=std::max(size_t(17),2*C+1);g.eager=true;g.bf16=g.same_device=g.metadata_typed=g.metadata_contiguous=true;g.offsets={0};for(size_t j=0;j<C;++j){g.offsets.push_back(int64_t((j+1)*W));g.reads.push_back(j+1);g.writes.push_back(j+1+(g.pool-1)/2);}bool expected=W>1&&W<=8&&C*W<=64;assert(kda_dispatch_r9150::eligible(g)==expected);++checks;for(int bad=0;bad<9;++bad){auto x=g;if(bad==0)x.bf16=false;if(bad==1)x.same_device=false;if(bad==2)x.metadata_typed=false;if(bad==3)x.metadata_contiguous=false;if(bad==4)x.H=3;if(bad==5)x.D=64;if(bad==6)x.offsets[0]=1;if(bad==7)x.offsets.back()+=1;if(bad==8)x.writes[0]=int64_t(x.pool);assert(!kda_dispatch_r9150::eligible(x));++checks;}}
{kda_dispatch_r9150::Input g;g.C=2;g.H=6;g.D=128;g.pool=17;g.eager=g.bf16=g.same_device=g.metadata_typed=g.metadata_contiguous=true;g.reads={1,2};g.writes={9,10};for(size_t W:{512ul,8ul,1ul}){g.T=2*W;g.offsets={0,int64_t(W),int64_t(2*W)};assert(kda_dispatch_r9150::eligible(g)==(W==8));++checks;}g.T=16;g.offsets={0,8,16};g.eager=false;assert(!kda_dispatch_r9150::eligible(g));++checks;}
std::cout<<"{\"passed\":true,\"pure_CPU\":true,\"checks\":"<<checks<<",\"D\":128,\"blocks\":[128,256],\"warp\":64,\"reduction_uses_blockDim\":true,\"GPU_tested\":false}"<<std::endl;}
